-- UTF-8. V309 after V308: preserve entry identity; correct only 17 reviewed tenant-1 Leads.
-- Source and business submitter become media/provider; original operator/audit and owner stay intact.
-- source_dept_id uses the existing contribution department snapshot, never current organization.
-- Only historical source classification is corrected (including frozen facts by explicit user decision).
-- Organization, people credited, timestamps, amounts, repurchase classification and workflow facts stay intact.
-- Orders retain their actual submitter; only approval leadProfile source keys are corrected.
-- Before/after images in zsjos_data_repair_backup are captured once; later conflicting edits fail closed.
-- DDL commits implicitly: a failed run may leave the nullable column. Re-execution checks actual state.
-- Empty fresh DB: additive schema only, no business seeds. Partial manifest rejects.
-- Restore requires matching after-images, reviewed before-image recovery and later-migration review.
-- Do not replay older V298/V301 repair scripts after this migration. No role/menu changes or notifications.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
DROP PROCEDURE IF EXISTS zsjos_v309_apply;
DELIMITER $$
CREATE PROCEDURE zsjos_v309_apply()
BEGIN
 DECLARE v_count INT;
 DECLARE v_now DATETIME DEFAULT NOW();
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF NOT EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V308') OR NOT EXISTS(SELECT 1 FROM zsjos_module_schema_version WHERE module_code='core' AND version='V308') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 requires V308 in both ledgers';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_data_repair_backup' AND column_name='old_value' AND data_type='longtext') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 requires LONGTEXT repair backup';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('zsjos_lead','zsjos_order_approval_round','zsjos_performance_attribution','zsjos_data_repair_backup','zsjos_schema_version','zsjos_module_schema_version') AND engine='InnoDB')<>6 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 requires transactional repair tables';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_lead' AND column_name='submission_source_type') THEN
  ALTER TABLE zsjos_lead ADD COLUMN submission_source_type VARCHAR(32) NULL COMMENT '录单入口身份来源，与业务引流来源分离' AFTER source_type;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_lead' AND column_name='submission_source_type' AND data_type='varchar' AND character_maximum_length=32 AND is_nullable='YES') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 incompatible entry identity column';
 END IF;
 DROP TEMPORARY TABLE IF EXISTS v309_manifest;
 CREATE TEMPORARY TABLE v309_manifest(lead_no VARCHAR(64) PRIMARY KEY,provider_id BIGINT NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
 INSERT INTO v309_manifest VALUES
('KZ202609211345520027',12),
('LD202608140010',26),
('LD202608200041',26),
('LD202608250009',26),
('LD202608280068',31),
('LD202608300016',26),
('LD202608300026',26),
('LD202608310022',26),
('LD202608310037',31),
('LD202609010051',31),
('LD202609040014',26),
('LD202609040073',26),
('LD202609090005',26),
('LD202609090036',26),
('LD202609100079',31),
('LD202609110010',26),
('LD202609160068',26);

 SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
 START TRANSACTION;
 SELECT COUNT(*) INTO v_count FROM zsjos_lead l JOIN v309_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1 FOR UPDATE;
 IF v_count NOT IN (0,17) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 partial manifest'; END IF;
 IF EXISTS(SELECT 1 FROM zsjos_lead l JOIN v309_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1 AND
  (l.deleted<>0 OR l.source_type NOT IN ('sales_self_sourced','internal_new_media') OR l.source_provider_recorded<>1
   OR NOT(l.source_provider_user_id <=> m.provider_id) OR NOT(l.provider_owner_type <=> 'system_user')
   OR NOT(l.provider_owner_id <=> m.provider_id) OR NOT(l.contribution_user_id_snapshot <=> m.provider_id)
   OR l.contribution_dept_id_snapshot IS NULL OR l.provider_owner_name_snapshot IS NULL OR l.partner_id IS NOT NULL)) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 reviewed provider evidence changed';
 END IF;
 DROP TEMPORARY TABLE IF EXISTS v309_images;
 CREATE TEMPORARY TABLE v309_images(table_name VARCHAR(64),row_id BIGINT,current_image JSON,before_image JSON,after_image JSON,PRIMARY KEY(table_name,row_id)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
 INSERT INTO v309_images SELECT 'zsjos_lead',l.id,JSON_OBJECT('source_type',l.source_type,'submission_source_type',l.submission_source_type,'source_user_id',l.source_user_id,'source_dept_id',l.source_dept_id,'version',l.version,'updater',l.updater,'update_time',DATE_FORMAT(l.update_time,'%Y-%m-%d %H:%i:%s')),JSON_OBJECT('source_type',l.source_type,'submission_source_type',l.submission_source_type,'source_user_id',l.source_user_id,'source_dept_id',l.source_dept_id,'version',l.version,'updater',l.updater,'update_time',DATE_FORMAT(l.update_time,'%Y-%m-%d %H:%i:%s')),JSON_SET(JSON_OBJECT('source_type',l.source_type,'submission_source_type',l.submission_source_type,'source_user_id',l.source_user_id,'source_dept_id',l.source_dept_id,'version',l.version,'updater',l.updater,'update_time',DATE_FORMAT(l.update_time,'%Y-%m-%d %H:%i:%s')),'$.submission_source_type','sales_self_sourced','$.source_type','internal_new_media','$.source_user_id',l.source_provider_user_id,'$.source_dept_id',l.contribution_dept_id_snapshot,'$.version',l.version+1,'$.updater','V309','$.update_time',DATE_FORMAT(v_now,'%Y-%m-%d %H:%i:%s')) FROM zsjos_lead l JOIN v309_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1;
 INSERT INTO v309_images SELECT 'zsjos_order_approval_round',r.id,JSON_OBJECT('order_snapshot',r.order_snapshot,'version',r.version,'updater',r.updater,'update_time',DATE_FORMAT(r.update_time,'%Y-%m-%d %H:%i:%s')),JSON_OBJECT('order_snapshot',r.order_snapshot,'version',r.version,'updater',r.updater,'update_time',DATE_FORMAT(r.update_time,'%Y-%m-%d %H:%i:%s')),JSON_SET(JSON_OBJECT('order_snapshot',r.order_snapshot,'version',r.version,'updater',r.updater,'update_time',DATE_FORMAT(r.update_time,'%Y-%m-%d %H:%i:%s')),'$.order_snapshot',JSON_SET(r.order_snapshot,'$.leadProfile.sourceType','internal_new_media','$.leadProfile.sourceLabel','新媒体提交','$.leadProfile.sourceUserName',l.provider_owner_name_snapshot,'$.leadProfile.sourceSubjectType','ADMIN','$.leadProfile.sourceSubjectId',l.source_provider_user_id),'$.version',r.version+1,'$.updater','V309','$.update_time',DATE_FORMAT(v_now,'%Y-%m-%d %H:%i:%s')) FROM zsjos_order_approval_round r JOIN zsjos_order o ON o.id=r.order_id AND o.tenant_id=r.tenant_id JOIN zsjos_lead l ON l.id=o.lead_id AND l.tenant_id=o.tenant_id JOIN v309_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1 AND o.deleted=0 AND r.deleted=0 AND JSON_TYPE(r.order_snapshot->'$.leadProfile')='OBJECT';
 INSERT INTO v309_images SELECT 'zsjos_performance_attribution',p.id,JSON_OBJECT('source_group',p.source_group,'updater',p.updater,'update_time',DATE_FORMAT(p.update_time,'%Y-%m-%d %H:%i:%s')),JSON_OBJECT('source_group',p.source_group,'updater',p.updater,'update_time',DATE_FORMAT(p.update_time,'%Y-%m-%d %H:%i:%s')),JSON_SET(JSON_OBJECT('source_group',p.source_group,'updater',p.updater,'update_time',DATE_FORMAT(p.update_time,'%Y-%m-%d %H:%i:%s')),'$.source_group','inbound','$.updater','V309','$.update_time',DATE_FORMAT(v_now,'%Y-%m-%d %H:%i:%s')) FROM zsjos_performance_attribution p JOIN zsjos_lead l ON l.id=p.lead_id AND l.tenant_id=p.tenant_id JOIN v309_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1 AND p.deleted=0 AND (p.source_group='self' OR EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='media-assisted-source-v309' AND b.table_name='zsjos_performance_attribution' AND b.row_id=p.id)) AND NOT(p.fact_type='ORDER' AND EXISTS(SELECT 1 FROM zsjos_order o WHERE o.id=p.fact_id AND o.tenant_id=p.tenant_id AND o.deleted=0 AND o.order_type='repurchase'));

 IF EXISTS(SELECT 1 FROM zsjos_data_repair_backup WHERE repair_key='media-assisted-source-v309' GROUP BY table_name,row_id,column_name HAVING COUNT(*)<>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 duplicate evidence'; END IF;
 IF EXISTS(SELECT 1 FROM zsjos_data_repair_backup b LEFT JOIN v309_images i ON i.table_name=b.table_name AND i.row_id=b.row_id WHERE b.repair_key='media-assisted-source-v309' AND (i.row_id IS NULL OR b.column_name NOT IN ('__before__','__after__'))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 evidence target missing'; END IF;
 IF EXISTS(SELECT 1 FROM v309_images i WHERE (SELECT COUNT(*) FROM zsjos_data_repair_backup b WHERE b.repair_key='media-assisted-source-v309' AND b.table_name=i.table_name AND b.row_id=i.row_id) NOT IN (0,2)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 incomplete images'; END IF;
 IF v_count=17 AND (EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V309') OR EXISTS(SELECT 1 FROM zsjos_module_schema_version WHERE module_code='core' AND version='V309')) AND (SELECT COUNT(*) FROM zsjos_data_repair_backup WHERE repair_key='media-assisted-source-v309')<>(SELECT COUNT(*)*2 FROM v309_images) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 ledger lacks evidence'; END IF;
 UPDATE v309_images i JOIN zsjos_data_repair_backup b ON b.repair_key='media-assisted-source-v309' AND b.table_name=i.table_name AND b.row_id=i.row_id AND b.column_name='__before__' JOIN zsjos_data_repair_backup a ON a.repair_key=b.repair_key AND a.table_name=b.table_name AND a.row_id=b.row_id AND a.column_name='__after__' SET i.before_image=CAST(b.old_value AS JSON),i.after_image=CAST(a.old_value AS JSON);
 IF EXISTS(SELECT 1 FROM v309_images WHERE current_image<>before_image AND current_image<>after_image) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 later edit conflicts with repair'; END IF;
 IF EXISTS(SELECT 1 FROM v309_images i WHERE i.table_name='zsjos_lead' AND i.before_image->>'$.source_type'<>'sales_self_sourced') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 original source evidence missing'; END IF;
 INSERT INTO zsjos_data_repair_backup(repair_key,table_name,row_id,column_name,old_value) SELECT 'media-assisted-source-v309',i.table_name,i.row_id,'__before__',CAST(i.before_image AS CHAR CHARACTER SET utf8mb4) FROM v309_images i WHERE NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='media-assisted-source-v309' AND b.table_name=i.table_name AND b.row_id=i.row_id AND b.column_name='__before__');
 INSERT INTO zsjos_data_repair_backup(repair_key,table_name,row_id,column_name,old_value) SELECT 'media-assisted-source-v309',i.table_name,i.row_id,'__after__',CAST(i.after_image AS CHAR CHARACTER SET utf8mb4) FROM v309_images i WHERE NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='media-assisted-source-v309' AND b.table_name=i.table_name AND b.row_id=i.row_id AND b.column_name='__after__');
 UPDATE zsjos_lead l JOIN v309_images i ON i.table_name='zsjos_lead' AND i.row_id=l.id SET l.source_type=NULLIF(i.after_image->>'$.source_type','null'),l.submission_source_type=NULLIF(i.after_image->>'$.submission_source_type','null'),l.source_user_id=NULLIF(i.after_image->>'$.source_user_id','null'),l.source_dept_id=NULLIF(i.after_image->>'$.source_dept_id','null'),l.version=NULLIF(i.after_image->>'$.version','null'),l.updater=NULLIF(i.after_image->>'$.updater','null'),l.update_time=NULLIF(i.after_image->>'$.update_time','null') WHERE l.tenant_id=1 AND i.current_image<>i.after_image;
 IF EXISTS(SELECT 1 FROM zsjos_lead l JOIN v309_images i ON i.table_name='zsjos_lead' AND i.row_id=l.id WHERE NOT(JSON_OBJECT('source_type',l.source_type,'submission_source_type',l.submission_source_type,'source_user_id',l.source_user_id,'source_dept_id',l.source_dept_id,'version',l.version,'updater',l.updater,'update_time',DATE_FORMAT(l.update_time,'%Y-%m-%d %H:%i:%s')) <=> i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 zsjos_lead postcondition failed'; END IF;
 UPDATE zsjos_order_approval_round r JOIN v309_images i ON i.table_name='zsjos_order_approval_round' AND i.row_id=r.id SET r.order_snapshot=i.after_image->'$.order_snapshot',r.version=NULLIF(i.after_image->>'$.version','null'),r.updater=NULLIF(i.after_image->>'$.updater','null'),r.update_time=NULLIF(i.after_image->>'$.update_time','null') WHERE r.tenant_id=1 AND i.current_image<>i.after_image;
 IF EXISTS(SELECT 1 FROM zsjos_order_approval_round r JOIN v309_images i ON i.table_name='zsjos_order_approval_round' AND i.row_id=r.id WHERE NOT(JSON_OBJECT('order_snapshot',r.order_snapshot,'version',r.version,'updater',r.updater,'update_time',DATE_FORMAT(r.update_time,'%Y-%m-%d %H:%i:%s')) <=> i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 zsjos_order_approval_round postcondition failed'; END IF;
 UPDATE zsjos_performance_attribution p JOIN v309_images i ON i.table_name='zsjos_performance_attribution' AND i.row_id=p.id SET p.source_group=NULLIF(i.after_image->>'$.source_group','null'),p.updater=NULLIF(i.after_image->>'$.updater','null'),p.update_time=NULLIF(i.after_image->>'$.update_time','null') WHERE p.tenant_id=1 AND i.current_image<>i.after_image;
 IF EXISTS(SELECT 1 FROM zsjos_performance_attribution p JOIN v309_images i ON i.table_name='zsjos_performance_attribution' AND i.row_id=p.id WHERE NOT(JSON_OBJECT('source_group',p.source_group,'updater',p.updater,'update_time',DATE_FORMAT(p.update_time,'%Y-%m-%d %H:%i:%s')) <=> i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V309 zsjos_performance_attribution postcondition failed'; END IF;

